import itertools, json

bands = ['U', 'V', 'W', 'X', 'Y', 'Z']

def base(s):
    # Constraints that stay in force under every option:
    # V (Vegemite) earlier than Z (Zircon); U (Uneasy) in slots 4-6; Y (Yardsign) in slots 1-3.
    return s['V'] < s['Z'] and s['U'] in (4, 5, 6) and s['Y'] in (1, 2, 3)

def original(s):
    # Original constraint set: W and Z each earlier than X.
    return base(s) and s['W'] < s['X'] and s['Z'] < s['X']

options = {
    'A': lambda s: all(s[b] < s['X'] for b in bands if b not in ('U', 'X')),
    'B': lambda s: s['V'] < s['W'] and s['W'] < s['Z'],
    'C': lambda s: s['V'] < s['X'] and s['W'] < s['X'],
    'D': lambda s: abs(s['X'] - s['U']) == 1,
    'E': lambda s: s['X'] in (5, 6),
}

def valid_set(pred):
    out = set()
    for perm in itertools.permutations(range(1, 7)):
        s = dict(zip(bands, perm))
        if pred(s):
            out.add(perm)
    return frozenset(out)

orig_set = valid_set(original)
evidence = {'original_count': len(orig_set), 'matches': {}}
matches = []
for label, extra in options.items():
    vs = valid_set(lambda s, e=extra: base(s) and e(s))
    same = (vs == orig_set)
    evidence['matches'][label] = {'count': len(vs), 'same_as_original': same}
    if same:
        matches.append(label)

if len(matches) == 1:
    final_answer = matches[0]
else:
    final_answer = 'UNSUPPORTED'

print(json.dumps({'final_answer': final_answer, 'evidence': evidence}, sort_keys=True))
